/// <summary>
/// Attributed mode: keys and membership come from the attributes on the formatted type itself.
/// A <c>[MessagePackObject]</c> type contributes its <c>[Key]</c> and <c>[IgnoreMember]</c> annotations;
/// a <c>[DataContract]</c> type contributes its <c>[DataMember]</c> and <c>[IgnoreDataMember]</c> annotations.
/// Every serialized member must be a public, read-write instance member.
/// </summary>
private static IReadOnlyList<MemberSerializationInfo>? CreateAttributedMembers(
    INamedTypeSymbol type,
    AttributeData contract,
    ReferenceSymbols referenceSymbols,
    Action<Diagnostic>? reportDiagnostic,
    Location location,
    out bool isIntKey)
{
    isIntKey = false;
    bool isDataContract = IsAttribute(contract, DataContractAttributeName);
    bool keyAsPropertyName = !isDataContract && contract.ConstructorArguments.Length == 1 && contract.ConstructorArguments[0].Value is true;
    bool? keyKindIsInt = null;
    HashSet<object> claimedKeys = new();
    List<MemberSerializationInfo> members = new();

    foreach (ISymbol member in GetInstanceMembers(type))
    {
        ImmutableArray<AttributeData> attributes = member.GetAttributes();
        Location memberLocation = member.Locations.FirstOrDefault(l => l.IsInSource) ?? location;
        object? key;
        if (isDataContract)
        {
            AttributeData? dataMember = attributes.FirstOrDefault(a => IsAttribute(a, DataMemberAttributeName));
            if (dataMember is null || attributes.Any(a => IsAttribute(a, IgnoreDataMemberAttributeName)))
            {
                continue;
            }

            int order = (dataMember.NamedArguments.FirstOrDefault(kvp => kvp.Key == "Order").Value.Value as int?) ?? -1;
            key = order >= 0
                ? (object)order
                : (dataMember.NamedArguments.FirstOrDefault(kvp => kvp.Key == "Name").Value.Value as string) ?? member.Name;
        }
        else
        {
            if (attributes.Any(a => SymbolEqualityComparer.Default.Equals(a.AttributeClass, referenceSymbols.IgnoreAttribute)))
            {
                continue;
            }

            if (keyAsPropertyName)
            {
                if (!IsPublicReadWrite(member))
                {
                    continue;
                }

                key = member.Name;
            }
            else
            {
                AttributeData? keyAttribute = attributes.FirstOrDefault(a => SymbolEqualityComparer.Default.Equals(a.AttributeClass, referenceSymbols.KeyAttribute));
                if (keyAttribute is null)
                {
                    if (member.DeclaredAccessibility != Accessibility.Public)
                    {
                        continue;
                    }

                    reportDiagnostic?.Invoke(Diagnostic.Create(MsgPack00xMessagePackAnalyzer.MemberNeedsKey, memberLocation, type.Name, member.Name));
                    return null;
                }

                key = keyAttribute.ConstructorArguments.Length == 1 ? keyAttribute.ConstructorArguments[0].Value : null;
                if (key is not (int or string))
                {
                    reportDiagnostic?.Invoke(Diagnostic.Create(MsgPack00xMessagePackAnalyzer.BothStringAndIntKeyAreNull, memberLocation, type.Name, member.Name));
                    return null;
                }
            }
        }

        bool memberIsIntKey = key is int;
        keyKindIsInt ??= memberIsIntKey;
        if (keyKindIsInt != memberIsIntKey)
        {
            reportDiagnostic?.Invoke(Diagnostic.Create(MsgPack00xMessagePackAnalyzer.DoNotMixStringAndIntKeys, memberLocation));
            return null;
        }

        if (!IsPublicReadWrite(member))
        {
            reportDiagnostic?.Invoke(Diagnostic.Create(
                MsgPack00xMessagePackAnalyzer.SerializedMemberNotSupported,
                memberLocation,
                member.Name,
                type.ToDisplayString(SymbolDisplayFormat.FullyQualifiedFormat)));
            return null;
        }

        if (!claimedKeys.Add(key))
        {
            reportDiagnostic?.Invoke(Diagnostic.Create(MsgPack00xMessagePackAnalyzer.KeysMustBeUnique, memberLocation));
            return null;
        }

        members.Add(key is int intKey
            ? CreateMember(member, intKey: intKey, stringKey: member.Name)
            : CreateMember(member, intKey: members.Count, stringKey: (string)key));
    }

    isIntKey = keyKindIsInt ?? false;
    return members;
}

